message.content:
{"diagnosis": "Loopback read via reg_dat_do returned 0xff (~0) instead of 0xa5 because recv_buf_valid never asserted with recv_buf_data. Reset leaves recv_state in 1 so receiver starts in half-bit wait using recv_divcnt vs cfg_divider while ser_rx is idle high instead of waiting in state 0 for start. The false start consumes timing and the real start bit is missed, so no byte is framed.", "patch_diff": "diff --git a/picosoc/simpleuart.v b/picosoc/simpleuart.v
--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -66,7 +66,7 @@
 	always @(posedge clk) begin
 		if (!resetn) begin
-			recv_state <= 1;
+			recv_state <= 0;
 			recv_divcnt <= 0;
 			recv_pattern <= 0;
 			recv_buf_data <= 0;
 			recv_buf_valid <= 0;
", "expected": "tohost PASS (FAIL 0xdead cleared), uart loopback got 0xa5 want 0xa5"}

